SELECT 
FROM sys_social_capability_binding
WHERE tenant_id = #{tenantId}
  AND connection_id = #{connectionId}
  AND capability = #{capability}
  AND del_flag = 0
LIMIT 1

SELECT 
FROM sys_social_capability_binding
WHERE tenant_id = #{tenantId}
  AND connection_id = #{connectionId}
  AND del_flag = 0
ORDER BY capability

SELECT COUNT(*)
FROM sys_social_capability_binding
WHERE tenant_id = #{tenantId}
  AND app_config_id = #{appConfigId}
  AND del_flag = 0
